<template>
    <section>
        <tg-list :showCheckBox="false" :IsShowAction="true" :listType="['List']" ModuleName="Asset"
            SubModuleCode="Asset" IdentityColumn="assetCatalogueId" :PageSize="PageSize" :HeaderText="$t('Vendor List')"
            :ListData="VendorData" :HeaderData="Headers" :widgets="widgets" :callbackfunction="GetDepreciationList"
            :HeaderButtons="listheaderbuttons" :TotalRecords="TotalRecords" :RenderRowActionMethod="renderActions"
            :ListDataCallBackFunction="GetDepreciationList" :LegendArray="LegendArray" :SortExp="SortExp"
            :SortBy="SortBy" :NorecordfoundText="$t('NoRecordfound')" v-on:LeftsearchButtonClick="leftCommonSearch"
            v-on:PagerButtonClick="pagerMethod" v-on:HeaderButtonClick="commonHeaderButtonClick"
            v-on:ActionButtonClick="actionButtonClick" v-on:SortdataButtonClick="sortdata">
            <template v-slot:slotdata="{ data }">

                <template v-if="data.column.COLUMN_NAME == 'created_at'">
                    <span :title="$options.filters.formatDateTimeMMDDYY(data.row.created_at)">{{
                        $options.filters.formatDateTimeMMDDYY(data.row.created_at)
                        }}</span>
                </template>

                <template v-if="data.column.COLUMN_NAME == 'status_id'">
                    <span v-if="data.row.status_id == 1001" class="px-2 bg-success text-center text-white d-block">
                        Active
                    </span>
                </template>
            </template>
        </tg-list>

        <VendorMapping v-if="IsVendorMapping" :AssetRequisitionId="AssetRequisitionId"></VendorMapping>
        <SendMail v-if="isSendMail" :AssetRequisitionId="AssetRequisitionId" :VendorDetails="vendorDetails"></SendMail>
        <ViewVendordetail v-if="IsViewVendordetail" :VendorViewdata="VendorViewdata"></ViewVendordetail>
    </section>
</template>
<script>
import Schema from '../../views/PurchaseOrder/VendorListingSchema.js'
import DataService from '../../service/DataService';
import VendorMapping from '../../views/PurchaseOrder/VendorMapping.vue'
import ViewVendordetail from '../../views/PurchaseOrder/ViewVendorDetail.vue'
import SendMail from './SendMail.vue'

export default {
    name: 'Depreciation',
    components: {
        VendorMapping,
        SendMail,
        ViewVendordetail
    },
    props: {

        AssetRequisitionId: {

        }
    },
    data() {
        return {
            IsViewVendordetail: false,
            IsVendorMapping: false,
            leftSearchFields: Schema.leftsearchSchema,
            listheaderbuttons: Schema.buttons,
            listActions: Schema.listActions,
            LegendArray: [],
            noRecordForTab: false,
            isLoading: false,
            DepreciationListData: [],
            widgets: [],
            Headers: [{
                "COLUMN_NAME": "vendor_name",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('Vendor Name'),
                "DISPLAY_ORDER": 1,
            },
            {
                "COLUMN_NAME": "phone_number",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('Phone Number'),
                "DISPLAY_ORDER": 2,
            },
            {
                "COLUMN_NAME": "email_id",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('Email'),
                "DISPLAY_ORDER": 3,

            },
            {
                "COLUMN_NAME": "vendor_owner",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('Vendor Owner Name'),
                "DISPLAY_ORDER": 4,
            },
            {
                "COLUMN_NAME": "created_at",
                "DATA_TYPE": "Date",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": "Created At",
                "DISPLAY_ORDER": 5,
                settings: {
                    isInSlot: true
                }
            },
            {
                "COLUMN_NAME": "created_by",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('Created By'),
                "DISPLAY_ORDER": 6,
            },
            {
                "COLUMN_NAME": "description",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('Description'),
                "DISPLAY_ORDER": 7,
            },
            {
                "COLUMN_NAME": "Street",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('Street'),
                "DISPLAY_ORDER": 8,
            },
            {
                "COLUMN_NAME": "city",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('City'),
                "DISPLAY_ORDER": 9,
            },
            {
                "COLUMN_NAME": "STATE",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('State'),
                "DISPLAY_ORDER": 10,
            },
            {
                "COLUMN_NAME": "country_name",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('Country'),
                "DISPLAY_ORDER": 11,

            },
            {
                "COLUMN_NAME": "status_id",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": "Status",
                "DISPLAY_ORDER": 12,
                settings: {
                    isInSlot: true
                }

            },
            // {
            //     "COLUMN_NAME": "status_id",
            //     "DATA_TYPE": "text",
            //     "SORTABLE": false,
            //     "VISIBLE": true,
            //     "DISPLAY_NAME": this.$t('Status'),
            //     "DISPLAY_ORDER": 12,

            // },
            {
                "COLUMN_NAME": "modified_by",
                "DATA_TYPE": "text",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": this.$t('Modified By'),
                "DISPLAY_ORDER": 13,

            }

            ],
            productName: '',
            LocationId: '',
            ProductTypeId: '',
            FromDate: '',
            ToDate: '',
            SortBy: '',
            SortExp: '',
            PageSize: 10,
            PageNumber: 1,
            TotalRecords: 0,
            CurrentPage: 1,
            TotalPages: 0,
            privilegeParams: null,
            UserType: null,
            searchCondition: "",
            VendorData: [],
            VendorViewdata: [],
            isSendMail: false,
            RequisitionId: 0,
            vendorDetails: {}
        }
    },
    created: async function () {
        var vm = this;
        vm.RequisitionId = vm.AssetRequisitionId
        vm.FetchData();
        //await vm.GetPageSize();
        // vm.privilegeParams = `controller=Asset&action=`;
        // await vm.CheckPrivilege();
        Schema.bindleftCommonSearchdropdown(vm, "Asset", "Product Type");
        Schema.bindleftCommonSearchdropdown(vm, "Asset", "Location");
        Schema.bindleftCommonSearchdropdown(vm, "Asset", "DepreciationDate");
        vm.UserType = vm.GetUserInfo.UserType;


    },
    methods: {

        FetchData: async function () {
            var vm = this;
            vm.isLoading = true;
            var params = `Requestion_id=${vm.AssetRequisitionId}`
            try {
                const response = await DataService.VendorListing(params);
                if (response.data && response.data.length > 0) {
                    vm.VendorData = response.data;
                } else {
                    vm.VendorData = [];
                }
            } catch (error) {
                console.error("Error fetching data:", error);
            } finally {
                vm.isLoading = false;
            }
        },

        Unmapvendor: function (data) {
            var vm = this
            this.isLoading = true;
            var msg = vm.$t("Are you sure you want to Unmap this Vendor?");
            vm.confirmR(msg, true, null,
                function () {
                    var parm = `vendorId=${data.vendor_id}&sourceId=${data.source_id}`;
                    DataService.UnmapVendor(parm).then(response => {
                        if (response.data == 'success') {
                            vm.ShowAlert(vm.$t("VendorUnmapSuccessfully"), 'success', true, vm.$t('Alert'));
                            // this.$parent.FetchData();
                            vm.CloseVendorpopup();
                            vm.FetchData();

                        }
                        else {
                            vm.ShowAlert(vm.$t('SomethingwentWrong'), "failure", true, vm.$t("Alert"));
                            //this.$parent.FetchData();
                            vm.CloseVendorpopup();
                        }
                        vm.isLoading = false;
                    })
                });
        },
        ViewVendorDetail(item) {
            this.VendorViewdata = item
            this.IsViewVendordetail = true
        },

        OpenVendorpopup: function (item) {
            var vm = this;
            vm.IsVendorMapping = true;
        },
        CloseVendorpopup: function () {
            var vm = this;
            vm.IsVendorMapping = false;
        },
        CloseViewVendor: function () {
            this.IsViewVendordetail = false
        },

        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
        },
        renderActions(row) {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    case 'Request For Quotation':
                        action.isVisible = true;
                        break;
                    case 'Unmap':
                        action.isVisible = true;
                        break;
                    case 'View':
                        action.isVisible = true;
                        break;
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        commonHeaderButtonClick(event) {
            switch (event.callbackfunction) {
                case "MapVendor":
                    this.OpenVendorpopup();
                    break;

            }
        },
        OpenSendmail(item) {
            this.vendorDetails = item;
            this.isSendMail = true;
        },
        actionButtonClick(callbackfunction, item) {

            var vm = this;
            switch (callbackfunction) {
                case "OpenSendmail":
                    vm.OpenSendmail(item)
                    break;
                case "Unmapvendor":
                    vm.Unmapvendor(item)
                    break;
                case "ViewVendorDetail":
                    vm.ViewVendorDetail(item);
                    break;
            }
        },
    }
}

</script>
<style>
.container-fluid.mt-2.p-0 {
    margin-top: 0px !important;
}

