<template>
    <section class="main-content">
        <loader :is-visible="isLoading"></loader>
        <div class="padding-t_10" id="reportstabsdata">
            <div class="left-menu-tab">
                <div class="col-md-12 p-0 ">
                    <div class="theme-primary partition">
                        <span class="p-name text-white" title=""> {{ $t('PurchaseRequest') }}</span>
                    </div>
                </div>
                <ul class="nav nav-pills flex-column left-tab mt-2 responivecustomtab  nav-tabs">
                    <li v-for="tab in tabs" :key="tab.id" @click="activeTab = tab.id, changeTab(tab.id)"
                        :class="{ 'nav-item': true, 'active': activeTab === tab.id }" style="cursor: pointer;">
                        <span :title="tab.title" data-toggle="tab" role="tab" data-toggle-tooltip="tooltip"
                            :class="{ 'nav-link left-menu': true, 'active': activeTab === tab.id }">
                            <i :class="tab.icon" class="p-1"></i> {{ tab.title }}</span>
                    </li>
                </ul>
            </div>
            <div class="right-content">
                <div class="tab-content" id="myTabContent">
                    <div class="expand-list">
                        <a href="javascript:;" class="expand-list-btn justify-content-center align-items-center">
                            <i class="icon-solid arrow-solid-left text-white" style="font-size:9pt"></i>
                        </a>
                    </div>
                    <!-- <div class="col-lg-12 mt-0 mb-2 p-0">
                        <div class="heading-border tablehead">
                            <h5 class="h5">
                                <span>{{ tabHeaderText }}</span>
                            </h5>
                        </div>
                    </div> -->

                    <div class="col-md-12 p-0" v-for="tab in tabs" :key="tab.id" v-show="activeTab === tab.id">
                        <ProductOverview v-if="isProductDetails && tab.id == 1" :id="AssetRequisitionId"
                            @ProductData="handleProductData">
                        </ProductOverview>
                        <QuotationListing v-if="isQuotation && tab.id == 3" :AssetRequisitionId="AssetRequisitionId"
                            :ProductDetail="ProductDetail"></QuotationListing>

                        <VendorListing v-if="isVendor && tab.id == 2" :AssetRequisitionId="AssetRequisitionId">
                        </VendorListing>
                    </div>
                </div>
            </div>
        </div>
    </section>
</template>
<script>

import ProductOverview from './ProductOverview.vue';
import VendorListing from './VendorListing.vue'
import QuotationListing from '../PurchaseOrder/QuotationListing.vue'
import DataService from '../../service/DataService';
export default {
    components: {
        ProductOverview,
        VendorListing,
        QuotationListing
    },
    data() {
        return {
            activeTab: 1,
            isProductDetails: false,
            isVendor: false,
            isQuotation: false,
            tabHeaderText: "",
            tabs: [
                {
                    title: this.$t('RequestDetail'),
                    icon: "fa fa-star",
                    id: 1
                }
            ],
            AssetRequisitionId: null,
            ProductDetail: {}
        }
    },

    async created() {
        var vm = this;
        vm.AssetRequisitionId = parseInt(vm.$route.params.id);
        let StatusName = vm.$route.params.status;
        if (StatusName == 'ACT' || StatusName == 'NEW_ASSET_REQUISITION_APPROVED' || StatusName == 'NEW_ASSET_REQUISITION_REJECTED')
            vm.GetPrivilege()
        vm.userName = vm.GetUserInfo.Name;
        vm.changeTab(1);
    },
    methods: {
        showTabs: function () {

        },

        // GetPrivilege: function (params) {
        //     debugger;
        //     var vm = this;
        //     if (this.GetUserInfo.UserType == "PM" || this.GetUserInfo.UserType == "CA") {

        //         vm.tabs.push({
        //             title: vm.$t('Vendor'),
        //             icon: "fa fa-trophy",
        //             id: 2
        //         },
        //             {
        //                 title: vm.$t('PurchaseQuotation'),
        //                 icon: "fa fa-file-o",
        //                 id: 3
        //             });

        //     }

        // },

        GetPrivilege: function (params) {
            var vm = this;
            var param = 'controller=AssetRequisition&action=ViewVendorMappingList';
            DataService.CheckPrivilege(param).then(function (response) {
                if (response.data) {
                    vm.tabs.push({
                        title: vm.$t('Vendor'),
                        icon: "fa fa-trophy",
                        id: 2
                    });
                }
                var param1 = 'controller=AssetRequisition&action=PurchaseQuotationList';
                DataService.CheckPrivilege(param1).then(function (response) {
                    if (response.data) {
                        vm.tabs.push({
                            title: vm.$t('PurchaseQuotation'),
                            icon: "fa fa-file-o",
                            id: 3
                        });
                    } else {
                        //
                    }
                });
            });
        },

        changeTab(tab) {
            var vm = this;
            vm.isProductDetails = tab === 1;
            vm.isVendor = tab === 2;
            vm.isQuotation = tab === 3;
            switch (tab) {
                case 1:
                    vm.tabHeaderText = 'Request Detail';
                    vm.isProductDetails = true;
                    break;
                case 2:
                    vm.tabHeaderText = 'Vendor';
                    vm.isVendor = true;
                    break;
                case 3:
                    vm.tabHeaderText = 'Purchase Quotation';
                    vm.isQuotation = true;
                    break;
                default:
                    break;
            }
        },

        handleProductData(data) {
            this.ProductDetail = data;
        }
    },

}
</script>