<template lang="en">
<div class="my-popups">
    <loader :is-visible="isLoading"></loader>

    <div class="modal d-block">
        <div class="modal-dialog modal-dialog-centered" style="max-width: 600px;">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">{{ $t('MapVendor') }}</h5>
                    <button v-on:click="ClosePOP($event)" type="button" class="close" data-original-title="Close"><em class="fa fa-times"></em></button>
                </div>
                <div class="border p-3">
                    <dynamic-form lang="en" ref="VendorMapping" :buttons="buttons" :schema="FormSchema" v-on:OnSubmit="onSubmit"></dynamic-form>
                </div>
            </div>
        </div>
    </div>
</div>
</template>

<script>
import DataService from '../../service/DataService'
export default {

    props: {
        AssetRequisitionId: {

        }
    },
    data() {
        return {
            ProductTypeId: 0,
            isLoading: false,
            vendorList: [],
            FormSchema: [{
                layoutType: "single",
                Data: [{
                    astype: "MultiSelectField",
                    label: this.$t('Vendor'),
                    name: "Vendor",
                    value: "",
                    mode: "tag",
                    placeholder: this.$t('Select') + " " + this.$t('Vendor'),
                    config: {
                        options: [],
                    },
                    validationRules: {
                        "required": true
                    }
                }, ]
            }],
            buttons: [{
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                },

                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.ClosePOP
                }
            ],
        }
    },
    created: function () {
        this.UpdateRequisition(this.AssetRequisitionId);

    },
    methods: {
        async getVendorlist() {
            var params = `Requestion_id=${this.AssetRequisitionId}&ProductType=${this.ProductTypeId}`
            await DataService.VendorForMapping(params).then((response) => {
                if (response.data != null) {
                    this.vendorList = response.data;
                    this.vendorList.forEach((itm) => {
                        this.FormSchema[0].Data[0].config.options.push({
                            name: itm.vendor_name,
                            value: itm.vendor_id
                        });
                    });
                    this.$refs.VendorMapping.UpdateKeyValue();
                }
            });
        },

        async UpdateRequisition(id) {
            this.isLoading = true;
            try {
                const params = `id=${id}`;
                const response = await DataService.UpdateRequisition(params);
                if (response.data) {
                    this.ProductTypeId = response.data.AssetTypeId;
                    this.getVendorlist();
                }
            } catch (error) {
                console.error("Error updating requisition:", error);
            } finally {
                this.isLoading = false;
            }
        },

        onSubmit: async function () {
            var vm = this
            // const result = await this.$refs.validatePlan.validateForm.validate();

            //if (result) {
            this.isLoading = true;

            const jsonobj = {
                Vendor: this.$refs.VendorMapping.getPropertyValue("Vendor", "value") == null ?
                    null :
                    Array.prototype.map.call(
                        this.$refs.VendorMapping.getPropertyValue("Vendor", "value"),
                        function (item) {
                            return item.value;
                        }
                    ).join(","),
                asset_requestion: this.AssetRequisitionId,
                source_name: "asset_requestion_Id",
                Sub_Module_Code: "asset_requestion",
                Is_Quotation: 1
            };
            var poststring = JSON.stringify(jsonobj);
            DataService.AddVendor(poststring).then(response => {
                if (response.data == 'Success') {
                    vm.ShowAlert(vm.$t("VendorMapSuccessfully"), 'success', true, vm.$t('Alert'));
                    this.$parent.FetchData();
                    vm.ClosePOP();
                } else {
                    vm.ShowAlert(vm.$t('SomethingwentWrong'), "failure", true, vm.$t("Alert"));
                    this.$parent.FetchData();
                    vm.ClosePOP();

                }
            })
            this.isLoading = false;

        },

        onCancel: function (item) {
            //
        },
        ClosePOP: function (item) {
            this.$parent.CloseVendorpopup();
        }
    }
}
</script>
