<template>
<div>
    <div class="col-md-12 p-0 mb-2">
        <div class="theme-primary tablehead  ticketsmallfix theme-primary partition p-actions-expand">
            <span class="p-name text-white">{{ $t('RequestDetail') }}</span>
             <span class="p-actions float-right">
            <a @click="EditRequestDetails" href="javascript:ShowCal();" value="cal" id="ShowCalender" class="p-action-btn text-white" title="" data-toggle-tooltip="tooltip" data-original-title="Back to List"><i class="fa fa-pencil"></i><br /><span> Edit</span></a>
            <a @click="BacktoList" href="javascript:ShowCal();" value="cal" id="ShowCalender" class="p-action-btn text-white" title="" data-toggle-tooltip="tooltip" data-original-title="Back to List"><i class="fa fa-angle-double-left pr-2"></i><br /><span> Back to List</span></a>
            </span>
        </div>
    </div>

    <div class="card mb-3 probx">
        <!-- <div class="card-header">
        <h2>Request Detail</h2>
      </div> -->
        <div class="card-body">
            <div class="row">

                <div class="col-sm-12 col-md-6 col-lg-4 col-xl-3">
                    <div class="form-group"><label><b>{{ $t("Location") }}:</b> {{ updateItemArray.location }}</label></div>
                </div>
                <div class="col-sm-12 col-md-6 col-lg-4 col-xl-3">
                    <div class="form-group"><label><b>{{ $t('ProductName') }}:</b> {{ updateItemArray.productName }}</label></div>
                </div>
                <div class="col-sm-12 col-md-6 col-lg-4 col-xl-3">
                    <div class="form-group"><label><b>{{ $t('ProductType') }}:</b> {{ updateItemArray.asset_type }}</label></div>
                </div>
                <div class="col-sm-12 col-md-6 col-lg-4 col-xl-3">
                    <div class="form-group"><label><b>{{ $t('RequestedQuantity') }}:</b> {{ updateItemArray.Quantity }}</label></div>
                </div>
                <div class="col-sm-12 col-md-6 col-lg-4 col-xl-3">
                    <div class="form-group"><label><b>{{ $t('Specification') }}:</b> {{ updateItemArray.Specification }}</label></div>
                </div>
                <div class="col-sm-12 col-md-6 col-lg-4 col-xl-3">
                    <div class="form-group"><label><b>{{ $t('Reason') }}:</b> {{ updateItemArray.description }}</label></div>
                </div>

            </div>
        </div>
    </div>
</div>
</template>

<script>
import DataService from "../../service/DataService"; // Adjust this import path

export default {
    props: {
        id: {
            type: Number,
            required: true
        }
    },
    data() {
        return {
            isLoading: false,
            updateItemArray: [],
        };
    },
    created() {
        this.UpdateRequisition(this.id);
    },
    methods: {
        BacktoList (){
            this.$router.push({
                                path: '/AssetRequisition/NewAssetRequisitionListing'
                            });
        },

        EditRequestDetails() {
            this.$router.push({ name: "AddNewRequisition", params: { reqForm: 'ProductEdit', items: this.updateItemArray } });

        },
        async UpdateRequisition(id) {
            this.isLoading = true;
            try {
                const params = `id=${id}`;
                const response = await DataService.UpdateRequisition(params);
                if (response.data) {
                    this.updateItemArray = response.data;
                    this.$emit('ProductData',response.data)
                }
            } catch (error) {
                console.error("Error updating requisition:", error);
            } finally {
                this.isLoading = false;
            }
        }
    }
};
</script>

