<template>
    <section class="main-content">
        <tg-list :IsShowAction="false" ref="tgList" :showCheckBox="false" ModuleName="CRM" SubModuleCode="CRM_QUOTES"
            IdentityColumn="Order_id" :HeaderText="$t('CRM_QUOTES')" :ListData="QuotationData" :HeaderData="Headers"
            :NorecordfoundText="$t('NoRecordfound')" :TotalRecords="TotalRecords" :SearchFields="false"
            :RenderRowActionMethod="renderActions" :ListDataCallBackFunction="FetchData" :LegendArray="LegendArray"
            :SortExp="SortExp" :SortBy="SortBy" :HeaderButtons="listheaderbuttons" :CurrentPageNumber="PageNumber"
            :widgets="[]" v-on:LeftsearchButtonClick="leftCommonSearch" v-on:PagerButtonClick="pagerMethod"
            v-on:HeaderButtonClick="commonHeaderButtonClick" v-on:ActionButtonClick="actionButtonClick"
            v-on:SortdataButtonClick="sortdata">
            <template v-slot:slotdata="{ data }">
                <template v-if="data.column.COLUMN_NAME == 'status_id'">
                   
                    <a class="px-2 bg-success text-center text-white d-block" v-if="data.row.status_id === 'Active'">
                        <span :class="data.row.status_id">
                            {{ data.row.status_id }}
                        </span>
                    </a>

                    <a class="px-2 bg-primary text-center text-white d-block"
                        v-else-if="data.row.status_id === 'Approved'">
                        <span :class="data.row.status_id">
                            {{ data.row.status_id }}
                        </span>
                    </a>

                    <a class="px-2 bg-danger text-center text-white d-block" v-else>
                        <span :class="data.row.status_id">
                            {{ data.row.status_id }}
                        </span>
                    </a>

                </template>

                <template v-if="data.column.COLUMN_NAME == 'attachment'" >

                    <a @click = "handleClick(data.row.Order_id)" style="cursor: pointer;" class="single-action">
                        <em class="fa fa-paperclip " aria-hidden="true"></em>
                    </a>
                </template>
            </template>
        </tg-list>

        <Compare v-if="isCompare" :AssetRequisitionId="AssetRequisitionId"></Compare>

        <QuotationAttachments v-if="ShowQuoteAttachment" v-on:close="ShowQuoteAttachment = false" :QuotationId = QuotationId></QuotationAttachments>
    </section>

</template>
<script>


import DataService from '../../service/DataService'
import Compare from './Compare.vue';
import QuotationAttachments from '../../components/Modal/QuotationAttachments.vue';

export default {

    components: {
        Compare,
        QuotationAttachments
    },
    props: {
        AssetRequisitionId: {
            type: String,
            required: true,
        },
        ProductDetail:{
          type:Object,
          required:true
        }

    },
    data() {
        return {
            isCompare: false,
            LegendArray: [],
            ViewList: [],
            isLoading: false,
            leftSearchFields: [],
            userid: null,
            usertype: null,
            searchCondition: '',
            selectedQuoteType: '',
            ddlQuoteType: '',
            Status: '',
            txtquotetitle: '',
            txtquotenumber: '',
            quotationNumberId: '',
            Title: '',
            QuotationType: '',
            quotationDateFrom: '',
            quotationDateTo: '',
            PageNumber: 1,
            PageSize: 10,
            SortBy: '',
            SortExp: '',
            Headers: null,
            noRecord: false,
            listActions: [],
            TotalRecords: 0,
            StatusListForListing: [],
            IsAnySearch: false,
            souceID: 0,
            QuotationData: null,
            showAddEventModal: false,
            ShowManageView: false,
            showFilter: false,
            showAddEmailTemplate: false,
            appliedFilter: [],
            privilegeParams: null,
            orderIdForConvertToProject: null,
            showQuoteToProjectModal: false,
            ViewListId: '',
            listheaderbuttons: [
                {
                    title: 'Send For Approval',
                    iconClass: 'fa fa-paper-plane',
                    callbackfunction: 'SendForApproval',
                    additionalClass: '',
                    isdisabled: false,
                    isvisible: true,
                    checkPrivilege: false
                },
                {
                    title: 'Add Quote',
                    iconClass: 'fa fa-plus',
                    callbackfunction: 'AddQuote',
                    additionalClass: '',
                    isdisabled: false,
                    isvisible: true,
                    checkPrivilege: false
                },
                // {
                //     title: 'Compare',
                //     iconClass: 'fas fa-thumbs-up',
                //     callbackfunction: 'Compare',
                //     additionalClass: '',
                //     isdisabled: false,
                //     isvisible: true,
                //     checkPrivilege: false
                // }

            ],
            IsShowManageQuote: false,
            ShowQuoteAttachment: false,
            QuotationId:null

        }
    },

    async created() {

        var vm = this;
        vm.userid = vm.GetUserInfo.ID;
        vm.usertype = vm.GetUserInfo.UserType;
        vm.getStatuslistForListing('CRM', 'en');
        vm.FetchData();

    },
    methods: {

        handleClick: function (QuoteId) {
            debugger

            var vm = this;
            vm.ShowQuoteAttachment = true;
            vm.QuotationId = QuoteId;
           
            $("#ShowSubModuleFields").modal('show');
            setTimeout(function () {
                $("#ShowSubModuleFields").modal('show');
                setTimeout(function () {
                    vm.SetBootstraptoolTip();
                }, 200);
            }, 1000);
        },

        FetchData: function () {
            debugger
            var VueObj = this;
            var params = `pageSize=${VueObj.PageSize}&pageNumber=${VueObj.PageNumber}&searchcondition=&pageNum=${VueObj.PageNumber}&isPaged=1&sortBy=${VueObj.SortBy}&sortExp=${VueObj.SortExp}&AssetRequisitionId=${VueObj.AssetRequisitionId}`;
            DataService.QuotesListing(params).then(function (response) {
                VueObj.isLoading = false;
                if (response.data.data.length == 0) {
                    VueObj.listheaderbuttons[0].isdisabled = true;
                }
                if (response.data != null) {
                    if (response.data.data && response.data.SendForApproval == "1") {
                        VueObj.listheaderbuttons[0].isdisabled = true;
                        VueObj.listheaderbuttons[1].isdisabled = true;
                        //VueObj.listheaderbuttons[2].isdisabled= true;
                    }
                    VueObj.Headers = response.data.schema;
                    VueObj.Headers.forEach((column) => {
                        column.DISPLAY_NAME = VueObj.$t(column.DISPLAY_NAME ? column.DISPLAY_NAME : column.COLUMN_NAME);
                        column.settings = null;
                        if (column.COLUMN_NAME == 'status_id') {
                            column.settings = {
                                isInSlot: true
                            }
                        }
                        if (column.COLUMN_NAME == 'attachment') {
                            column.settings = {
                                isInSlot: true
                            }
                        }
                        if (column.COLUMN_NAME == 'order_number') {
                            column.settings = {
                                clickEvent: VueObj.clickEventOfColumn,
                                formatter: VueObj.columnDataFormatter
                            }
                        }

                    });

                    if (response.data.data.length > 0) {
                        VueObj.QuotationData = response.data.data;
                        VueObj.QuotationData.forEach((row) => {
                            row.isCheckBoxDisabled = false;
                            row.additionalClass = '';
                            if (row.status_id == 'Closed') {
                                row.isCheckBoxDisabled = true;
                                row.additionalClass = 'warning-bar';
                            }
                            row.rowDetailsUrl = '';
                            if (row.rowDetailsUrl == '') {
                                row.rowDetailsUrl = '/CRM/ViewQuotationDetails/' + row.Order_id + '/CRM/CRM_QUOTES';
                            }
                        })
                        VueObj.TotalRecords = response.data.data[0].total_records;
                        VueObj.TotalPages = Math.ceil(VueObj.TotalRecords / VueObj.PageSize);
                        VueObj.CurrentPage = VueObj.PageNumber;

                    }
                    else {
                        VueObj.noRecord = true;
                        VueObj.QuotationData = [];
                        VueObj.TotalRecords = 0
                    }
                } else {
                    VueObj.noRecord = true;
                    VueObj.QuotationData = [];
                    VueObj.Headers = [];
                    VueObj.TotalRecords = 0
                }
                VueObj.isLoading = false;

            });
        },

        SendForApproval: async function () {
            
            var vm = this;
            vm.isLoading = true;
            var params = `RequisitionId=${vm.AssetRequisitionId}&productName=${vm.ProductDetail.productName}`;

            try {
                const response = await DataService.SendforApproval(params);
                if (response.data.result == "1") {
                    vm.ShowAlert(vm.$t("SendApproveSuccessfully"), 'success', true, vm.$t('Alert'));
                    vm.listheaderbuttons[0].isdisabled = true;
                    vm.listheaderbuttons[1].isdisabled = true;
                    vm.FetchData();
                }
            } catch (error) {
                console.error("Error fetching data:", error);
            } finally {
                vm.isLoading = false;
            }
        },

        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchData();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchData();
        },
        leftCommonSearch() { },
        renderActions() { },
        commonHeaderButtonClick: function (event) {
            debugger
            switch (event.callbackfunction) {
                case "AddQuote":
                    this.AddQuote();
                    break;
                case "Compare":
                    this.Compare();
                    break;
                case "SendForApproval":
                    this.SendForApproval();
                    break
            }
        },
        actionButtonClick() { },
        getStatuslistForListing: function (StatusType, lang) {

            var vm = this;
            var url = "langCode=" + lang + "&statusType=" + StatusType + "&hasglobal=true";

            DataService.statusdropdown(url).then(function (response) {
                if (response.data.status == "Success") {
                    var json = response.data.result;
                    vm.StatusListForListing = json.data;
                }
            });
        },

        AddQuote() {

            this.$router.push(`/AssetRequisition/AddPurchaseQuotation/${this.AssetRequisitionId}/0`);
        },
        Compare() {

            var param1 = 'controller=AssetRequisition&action=PurchaseRequestApproval';
            DataService.CheckPrivilege(param1).then((response) => {
                if (response.data) {
                    this.isCompare = true;
                } else {
                    this.isCompare = false;
                    // Maybe notify user
                }
            }).catch((error) => {
                this.ShowAlert(this.$t('NotAuthorizedSection'), "failure", true, "Alert");
                // Handle error (e.g., show notification)
            });
        }

    },

}
</script>