<template>
    <div id="ShowSubModuleFields" role="dialog" class="modal my-popups fade" v-cloak>
        <div role="document" class="modal-dialog" style="top:0px!important; width: 800px;">
            <div class="modal-content">
                <div class="modal-header mheader-user">
                    <button type="button" class="close" v-on:click="close()">
                        <em aria-hidden="true" class="fa fa-times"></em>
                    </button>
                    <h4 id="myModalLabel" class="modal-title">Quotation Attachment</h4>

                </div>
                <div class="modal-body">
                    <loader :isVisible="isLoading"></loader>

                    <div id="modalContent">
                        <template>

                         <div class="listing">
                            <div class="table-responsive table-fix-header">
                            <table class="table table-bordered mt-0">
                                <thead class="thead-bg">
                                    <tr>
                                        <th>Attchment URL</th>
                                    </tr>
                                </thead>
                                <tbody>
                                     <tr v-for="(item, index) in AttachmentData" :key="index">
                                        <td><a :href="item.Link" target="_blank" rel="noopener noreferrer">
                                         {{ item.Link }}
                                    </a></td>
                                    </tr>
                                </tbody>
                            </table>
                            </div>
                         </div>
                          
                        </template>
                    </div>

                    <div v-if="AttachmentData.length == 0" class="text-center text-danger no-record border p-2 mt-2">
                        No records found
                    </div>

                </div>
            </div>
        </div>
    </div>

</template>

<script>
import DataService from "../../service/DataService";
export default {
    props: {
        QuotationId: {
            type: Number,
            Required: true
        },

    },
     watch: {
        QuotationId(newVal, oldVal) {
            debugger
            if (newVal || oldVal) {
                this.FetchAttachmentData();
            }
        },       
    },
    data() {
        return {
            isLoading: false,
            AttachmentData: []
        }
    },
    created: function () {
        debugger
        var vm = this;
        vm.FetchAttachmentData();
    },

    methods: {

        close: function () {

            var vm = this;

            $("#ShowSubModuleFields").modal("hide");
            $("body").removeClass("modal-open");
            $(".modal-backdrop").remove();

        },

        FetchAttachmentData: function () {
            debugger
            var VueObj = this;
            var params = `QuotationId=${VueObj.QuotationId}`;

            DataService.QuotesAttachment(params).then(function (response) {
                VueObj.isLoading = false;
                if (response.data.length != 0) {
                    VueObj.AttachmentData = response.data.Data;
                }

                VueObj.isLoading = false;

            });
        },



    }
}
</script>
