<template>
    <section>
        <div class="my-popups">
            <div class="modal d-block">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">
                                {{ $t('Compare') }}
                            </h5>
                            <button v-on:click="closePopup()" type="button" class="close" title="Close"><em
                                    class="fa fa-times"></em></button>
                        </div>

                        <div class="modal-body">
                            <div class="col-lg-12 mt-0 mb-2 p-0 float-left">
                                <div class="col-lg-12 mt-2 mb-3 p-0 float-left">
                                    <div class="heading-border tablehead mb-3">
                                        <h5 class="h5">
                                            <span>{{ $t('ProductRequestDetails') }}</span>
                                        </h5>
                                    </div>
                                    <div class="row">
                                        <div class="col-md-6 col-lg-3">
                                            <div class="form-group"><label><b>{{ $t('Location') }}:</b> {{
                                                updateItemArray.location
                                                    }}</label></div>
                                        </div>
                                        <div class="col-md-6 col-lg-3">
                                            <div class="form-group"><label><b>{{ $t('ProductName') }}:</b> {{
                                                updateItemArray.productName }}</label></div>
                                        </div>
                                        <div class="col-md-6 col-lg-3">
                                            <div class="form-group"><label><b>{{ $t('ProductType') }}:</b> {{
                                                updateItemArray.asset_type }}</label></div>
                                        </div>
                                        <div class="col-md-6 col-lg-3">
                                            <div class="form-group"><label><b>{{ $t('RequestedQuantity') }}:</b> {{
                                                updateItemArray.Quantity }}</label></div>
                                        </div>
                                        <div class="col-md-6 col-lg-3">
                                            <div class="form-group"><label><b>{{ $t("CreatedAt") }}</b>
                                                    {{ $options.filters.formatDateTimeMMDDYYY(
                                                        updateItemArray.created_at) }} </label></div>
                                        </div>
                                        <div class="col-md-6 col-lg-3">
                                            <div class="form-group"><label><b>{{ $t("CreatedBy") }}</b> {{
                                                updateItemArray.created_by }}</label></div>
                                        </div>
                                        <div class="col-md-6 col-lg-3">
                                            <div class="form-group"><label><b>{{ $t('Specification') }}:</b> {{
                                                updateItemArray.Specification }}</label></div>
                                        </div>
                                        <div class="col-md-12 col-lg-12">
                                            <div class="form-group"><label><b>{{ $t('Reason') }}:</b> {{
                                                updateItemArray.description
                                                    }}</label></div>
                                        </div>

                                    </div>
                                </div>

                                <div class="col-lg-12 mt-0 mb-2 p-0 float-left">
                                    <div class="heading-border tablehead">
                                        <h5 class="h5">
                                            <span>{{ $t('VendorPriceComparsionChart') }}</span>
                                        </h5>
                                    </div>
                                    <apexchart type="bar" height="350" :options="chartOptions" :series="series" />
                                </div>
                            </div>

                            <div class="col-lg-12 mt-0 mb-2 p-0 float-left">
                                <div class="heading-border tablehead">
                                    <h5 class="h5">
                                        <span>{{ $t('CompareVendorQuotes') }}</span>
                                    </h5>
                                </div>
                                <loader :is-visible="isLoading"></loader>
                                <tg-list :showCheckBox="true" :IsShowAction="false" :listType="['List']"
                                    ModuleName="Asset" SubModuleCode="Asset" IdentityColumn="source_id"
                                    :PageSize="PageSize" :HeaderText="$t('Vendor List')" :ListData="VendorData"
                                    :HeaderData="Headers" :widgets="[]" :HeaderButtons="false"
                                    :TotalRecords="TotalRecords" :RenderRowActionMethod="renderActions"
                                    :LegendArray="LegendArray" :SortExp="SortExp" :SortBy="SortBy"
                                    :NorecordfoundText="$t('NorecordfoundText')"
                                    v-on:LeftsearchButtonClick="leftCommonSearch" v-on:PagerButtonClick="pagerMethod"
                                    v-on:HeaderButtonClick="commonHeaderButtonClick"
                                    v-on:ActionButtonClick="actionButtonClick" v-on:SortdataButtonClick="sortdata">
                                    <template v-slot:slotdata="{ data }">

                                        <template v-if="data.column.COLUMN_NAME == 'delivery_date'">
                                            <span :title="$options.filters.formatDateTime(data.row.delivery_date)">{{
                                                $options.filters.formatDateTime(data.row.delivery_date) }}</span>
                                        </template>
                                        <template v-if="data.column.COLUMN_NAME == 'status_id'">
                                            <span :title="data.row.STATUS_NAME" :class="getStatusClass(data.row)">
                                                {{ getStatusLabel(data.row) }}
                                            </span>
                                        </template>
                                        <template v-if="data.column.COLUMN_NAME == 'quote'">

                                            <span style="cursor:pointer" title="Download">
                                                <em class="fa fa-download text-primary action-icon"></em>
                                            </span>

                                        </template>

                                        <template v-if="data.column.COLUMN_NAME == 'comments'">
                                            <input class="form-control" :disabled="data.row.isCheckBoxDisabled"
                                                placeholder="Enter comments" v-model="data.row.comments" />

                                        </template>
                                        <template v-if="data.column.COLUMN_NAME == 'attachment'">

                                            <a @click="handleClick(data.row.source_id)" style="cursor: pointer;"
                                                class="single-action">
                                                <em class="fa fa-paperclip " aria-hidden="true"></em>
                                            </a>
                                        </template>

                                    </template>
                                </tg-list>

                                <div class="col-12 float-left p-0 mt-3" v-if="IsApprovedStatus">
                                    <div class="row flex-row-reverse">
                                        <div class="col-lg-6 text-right">
                                            <!-- 
                                            <a id="exportButton" class="btn btn-info mr-1" href="javascript:;"
                                                title="Export" data-toggle-tooltip="tooltip"
                                                data-original-title="Export"><em
                                                    class="fa fa-file-text-o pr-2"></em>Export</a> -->

                                            <a id="approveButton" class="btn btn-success mr-1" href="javascript:;"
                                                title="Approve" data-toggle-tooltip="tooltip"
                                                v-on:click="updateQuotationStatus('approved')"
                                                data-original-title="Approve"><em class="fa fa-save pr-2"></em>{{
                                                    $t('Approve') }}</a>

                                            <a id="rejectButton" class="btn btn-danger" href="javascript:;"
                                                title="Reject" data-toggle-tooltip="tooltip"
                                                v-on:click="updateQuotationStatus('rejected')"
                                                data-original-title="Reject"><em class="fa fa-times pr-2"></em> {{
                                                    $t('Reject') }}</a>


                                        </div>
                                        <div class="col-lg-6 text-danger"> {{ $t('MandatoryString') }}
                                        </div>
                                    </div>
                                </div>

                            </div>
                            <QuotationAttachments v-if="ShowQuoteAttachment" v-on:close="ShowQuoteAttachment = false"
                                :QuotationId=QuotationId>
                            </QuotationAttachments>

                        </div>
                    </div>

                </div>

            </div>
