    methods: {
        closePopup() {
            this.$parent.isCompare = false;
        },

        handleClick (QuoteId) {
            
            debugger;
            var vm = this;
            vm.ShowQuoteAttachment = true;
            vm.QuotationId = QuoteId;
           
            $("#ShowSubModuleFields").modal('show');
            setTimeout(function () {
                $("#ShowSubModuleFields").modal('show');
                setTimeout(function () {
                    vm.SetBootstraptoolTip();
                }, 200);
            }, 1000);
        },
        async UpdateRequisition(id) {
            this.isLoading = true;
            try {
                const params = `id=${id}`;
                const response = await DataService.UpdateRequisition(params);
                if (response.data) {
                    this.updateItemArray = response.data;
                }
            } catch (error) {
                console.error("Error updating requisition:", error);
            } finally {
                this.isLoading = false;
            }
        },
        loadChartDataFromJSON(dataArray) {
            this.names = [];
            this.dataValues = [];
            let sortedData = dataArray.slice().sort((a, b) => a.unit_price - b.unit_price);
            sortedData.forEach(item => {
                this.names.push([item.vendor_name]);
                this.dataValues.push(item.unit_price);
            });
        },

        async FetchData() {
            this.isLoading = true;
            this.noRecord = false;
            try {
                const params = `requisitionId=${this.AssetRequisitionId}&pageNumber=${this.PageNumber}&pageSize=${this.PageSize}&sortColumn=${this.SortBy}&sortDirection=${this.SortExp}`;
                const response = await DataService.GetCompareVendorList(params);
                if (response && response.data) {
                    let responseData = JSON.parse(response.data.result).data
                    if (responseData.length > 0) {
                        const disabledStatuses = ['NEW_ASSET_REQUISITION_APPROVED', 'NEW_ASSET_REQUISITION_REJECTED'];
                        responseData.forEach(ele => {
                            if (ele.status_code == 'NEW_ASSET_REQUISITION_APPROVED' || ele.status_code == 'NEW_ASSET_REQUISITION_REJECTED') {
                                this.IsApprovedStatus = false
                            }
                           //ele.comments = '';
                            ele.isCheckBoxDisabled = disabledStatuses.includes(ele.status_code);
                        });
                        this.VendorData = responseData;
                        this.TotalRecords = responseData[0].total_records || 0;
                        this.TotalPage = Math.ceil(this.TotalRecords / this.pageSize);
                        this.CurrentPage = this.PageNumber;
                        this.loadChartDataFromJSON(responseData);
                    } else {
                        this.noRecord = true;
                        this.VendorData = [];
                        this.TotalRecords = 0;
                        this.TotalPage = 0;
                        this.CurrentPage = 1;
                    }
                } else {
                    this.noRecord = true;
                    this.VendorData = [];
                }
            } catch (error) {
                console.error("Error fetching vendor data:", error);
                this.noRecord = true;
                this.VendorData = [];
            } finally {
                this.isLoading = false;
            }
        },

        renderRowActionMethod() {

        },
        pagerMethod(value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchData();
        },

        sortdata(s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }

            this.FetchData();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },

        getStatusClass(row) {

            switch (row.status_code) {
                case 'NEW_ASSET_REQUISITION_REJECTED':
                    return "btn btn-danger py-0 d-block font-14";
                case 'NEW_ASSET_REQUISITION_APPROVED':
                    return "btn btn-primary py-0 d-block font-14";
                case 'ACT':
                    return "btn btn-success py-0 d-block font-14";
                default:
                    return "btn btn-secondary py-0 d-block font-14"; // Default class if status is unknown
            }
        },

        getStatusLabel(row) {
            switch (row.status_code) {
                case 'NEW_ASSET_REQUISITION_APPROVED':
                    return "Approved";
                case 'NEW_ASSET_REQUISITION_REJECTED':
                    return "Rejected";
                case 'ACT':
                    return "Active";
                default:
                    return row.status_code;
            }
        },

        async updateQuotationStatus(actionType) {

            let val = "";
            $('.chkItems:checkbox:checked').not("[id^='chkAll']").each(function () {
                if (val.length > 0)
                    val += ',';
                val += $(this).val();
            });

            if (val.length > 0) {
                const sourceIds = val.replace(/"/g, '').split(',').map(Number);
                if (sourceIds.length > 1) {
                    return this.ShowAlert(this.$t("SelectOneVendor"), 'warning', true, this.$t('Alert'));
                }
                else {
                    let selectedValues = this.VendorData.filter(item => sourceIds.includes(item.source_id));
                    let quotationDetails = [];
                    selectedValues.forEach(ele => {
                        let obj = {
                            assetRequestionId: this.AssetRequisitionId,
                            vendorId: ele.account_id,
                            quantity: ele.quantity,
                            unit_price: ele.unit_price,
                            amount: ele.amount,
                            comments: ele.comments
                        };
                        quotationDetails.push(obj);
                    });
                    let type = actionType;
                    let orderIds = val;
                    let postVendorData = {
                        type: type,
                        orderIds: orderIds,
                        QuotationDetails: quotationDetails
                    };
                    const formData = new FormData();
                    formData.append("postString", JSON.stringify(postVendorData));
                    try {
                        const response = await DataService.ApproveOrRejectQuotation(formData);
                        if (response?.data?.result) {
                            debugger
                            if (JSON.parse(response.data.result).STATUS_CODE == 1) {
                                var ordernum = JSON.parse(response.data.result).OrderNumber;
                                if (actionType == 'approved') {
                                    this.FetchData();
                                    this.ShowAlert(`${this.$t("ApprovedQuatation")}  ${this.$t('With Purchase Order Number')}: ${ordernum}`, 'Success', true, this.$t('Alert'));
                                } else if (actionType == 'rejected') {
                                    this.FetchData();
                                    this.ShowAlert(this.$t("RejectQuatation"), 'Success', true, this.$t('Alert'));
                                }
                                this.$parent.FetchData();
                                this.$parent.isCompare = false;

                            }
                        } else {
                            // console.error("Invalid response structure:", response);
                        }
                    } catch (error) {
                        console.error("An error occurred while saving the email template:", error);
                    } finally {
                        this.isLoading = false;
                    }

                }
            }
            else {
                return this.ShowAlert(this.$t("SelectVendorQuotation"), "warning", this.$t("Alert"));

            }
        },


