<template>
    <section>
        <div class="my-popups">
            <div class="modal d-block">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">
                                {{ $t('Request For Quotation') }}
                            </h5>
                            <button v-on:click="closePopup()" type="button" class="close" title="Close"><em
                                    class="fa fa-times"></em></button>
                        </div>
                        <div class="modal-body">
                            <dynamic-form ref="FieldUpdate" :mandatorytext="MandatoryString" :buttons="buttons"
                                :schema="FormSchema" v-on:OnSubmit="onSubmit">
                                <template v-slot:tgslot-Description="{ data }">
                                    <ckeditor :editor="editor" @ready="onReady" v-model="Description">
                                    </ckeditor>
                                    <span name="Description" class="invalid-feedback d-block">{{ data.error }}</span>
                                </template>
                            </dynamic-form>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </section>

</template>
<script>

import DataService from '../../service/DataService';

export default {

    props: {
        AssetRequisitionId: {
            type: Number
        },
        VendorDetails: {
            type: Object
        }
    },
    data() {
        return {
            Description: '',
            isLoading: false,
            editor: this.CLASSIC_EDITOR,
            MandatoryString: this.$t('MandatoryString'),
            FormSchema: [
                {
                    layoutType: "double",
                    Data: [
                        {
                            astype: "SelectField",
                            label: this.$t('Template'),
                            name: "Select_Template",
                            value: "",
                            validationRules: { "required": true, },
                            placeholder: "",
                            config: {
                                options: [

                                ],
                                onChange: this.getEmailTemplateBytemplateId

                            },
                        },
                        {
                            astype: "TextField",
                            label: this.$t("Subject"),
                            name: "Subject",
                            value: '',
                            placeholder: "",
                            validationRules: { "required": true },

                        },
                        {
                            astype: "TextField",
                            label: this.$t('To'),
                            name: "To",
                            value: "",
                            validationRules: { "required": true, },
                            placeholder: "",
                        },
                        {
                            astype: "TextField",
                            label: this.$t('Cc Users'),
                            name: "cc_users",
                            value: "",
                            validationRules: { "required": false, },
                            placeholder: "",
                        },
                        {
                            astype: "TextField",
                            label: this.$t('Bcc'),
                            name: "bcc",
                            value: "",
                            validationRules: { "required": false, },
                            placeholder: "",
                        },
                    ]
                },
                {
                    layoutType: "Single",
                    Data: [
                        {
                            astype: "SlotField",
                            label: this.$t('Description'),
                            name: "Description",
                            value: "",
                            placeholder: "",
                            config: {
                                options: [],
                            },
                            settings: {
                                isInSlot: true
                            },
                            visibility: true,
                            validationRules: { "required": true, max: 5000 },
                        }
                    ]
                }


            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-sent pr-2'></i>Send",
                },

                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.closePopup,
                }
            ],
        }
    },
    created() {
        this.getTemplates();
    },
    mounted() {
        this.$refs.FieldUpdate.updateProperty("To", "value", this.VendorDetails.email_id);
    },
    methods: {
        async onSubmit(fields, data) {
            this.isLoading = true;
            const obj = {
                EmailSubject: fields.Subject,
                EmailTo: fields.To,
                EmailCc: fields.cc_users,
                EmailBcc: fields.bcc,
                VendorMappingId: this.VendorDetails.vendor_id,
                EmailContent: this.Description,
            };
            const formData = new FormData();
            formData.append("postString", JSON.stringify(obj));

            try {
                const response = await DataService.SaveEmailTemplateDetails(formData);
                if (response?.data?.result) {
                    if (response.data.result == '1') {
                        this.$parent.isSendMail = false;
                        return this.ShowAlert(this.$t("EmailSendtMessage"), 'Success', true, this.$t('Alert'));
                    }
                } else {
                    console.error("Invalid response structure:", response);
                }
            } catch (error) {
                console.error("An error occurred while saving the email template:", error);
            } finally {
                this.isLoading = false;
            }
        },


        async getTemplates() {
            const vm = this;
            vm.isLoading = true;
            let url = `templateId=77`;
            try {
                const response = await DataService.GetTemplates(url);
                if (response?.data?.result) {
                    const responseData = JSON.parse(response.data.result).data;
                    if (Array.isArray(responseData) && responseData.length > 0) {
                        let templateData = [];
                        let obj = {};
                        responseData.map(item => {
                            obj = {
                                name: item.template_name,
                                value: item.template_id
                            };
                            templateData.push(obj)
                        });
                        vm.$refs.FieldUpdate.updateProperty("Select_Template", "config.options", templateData);
                        vm.$refs.FieldUpdate.UpdateKeyValue();
                    } else {
                        console.warn('No valid data found in the response');
                    }
                } else {
                    console.error('Invalid response structure:', response);
                }
            } catch (error) {
                //
            } finally {
                vm.isLoading = false;
            }
        },

        async getEmailTemplateBytemplateId(event, data) {
            const vm = this;
            vm.isLoading = true;
            let url = `templateId=${data.value}&requistionId=${vm.AssetRequisitionId}&vendorName=${vm.VendorDetails.vendor_name}`;
            try {
                const response = await DataService.GetEmailTemplate(url);
                if (response?.data?.result) {
                    const templateDetails = JSON.parse(response.data.result)
                    vm.Description = templateDetails.email_template;
                    vm.$refs.FieldUpdate.updateProperty("Subject", "value", templateDetails.template_subject);
                } else {
                    console.error('Invalid response structure:', response);
                }
            } catch (error) {
                //
            } finally {
                vm.isLoading = false;
            }
        },
        closePopup() {

            this.$parent.isSendMail = false
        },
        onReady(editor) {
            editor.ui.getEditableElement().parentElement.insertBefore(
                editor.ui.view.toolbar.element,
                editor.ui.getEditableElement()
            );
            let mediaIcon = document.getElementsByClassName('ck-dropdown')[2]
            mediaIcon.remove();
            var divToRemove = document.querySelector('.ck-file-dialog-button');
            divToRemove.remove();
            let ArrowIcon = document.getElementsByClassName('ck ck-button ck-off')[8]
            ArrowIcon.remove();
        }

    }

}

</script>